=== Claim


/** A person's claim on a sheet. {@code amount} has two decimals and is 0.00 or more, or negative for
 *  a correction, which names the number of the settled claim of its person it corrects; it starts
 *  as {@link ClaimStatus#DRAFT}. */
public class Claim {
    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private boolean statedNa;
    private String corrects;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private int proofs;
    private int proofPhotos;
    private String splitFrom;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private boolean escalated;
    private LocalDate reviewOn;
    private LocalDate pendingOn;
    private boolean waived;
    private boolean held;
    private String ref;
    private String tags;
    private String shares;
    private String reviewUser;
    private String voidReason;
    private String editedBy;
    private Long batch;

    private long addedSeq;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
            BigDecimal statedDue, String corrects, LocalDate dueBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
        this.dueBy = dueBy;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public LocalDate getDate() { return date; }
    public String getNote() { return note; }
    public ClaimStatus getStatus() { return status; }
    /** The number given when the claim was opened (the sheet-wide 1, 2, ..., or <period>-<n> / X-<n>
     *  while the sheet numbers by period); null for a draft, or a claim voided as a draft;
     *  a claim voided once open keeps it. */
    public String getNumber() { return number; }
    /** The due fixed when the claim was settled; null when not settled, or settled with no rate. */
    public BigDecimal getSettledDue() { return settledDue; }
    /** The user who opened the claim; null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    /** Whether the person's last statement bound the claim to its figure then. */
    public boolean isStated() { return stated; }
    /** The due as shown (late charge and floor included) the claim was bound to by the person's last statement; null when it had none (n/a)
     *  or is not bound. */
    public BigDecimal getStatedDue() { return statedDue; }
    /** Whether the person's last statement bound the claim to n/a: the rate that would apply to it had
     *  ended (its to-date) before the claim's date. */
    public boolean isStatedNa() { return statedNa; }
    /** Whether the claim keeps the figure its person's last statement bound it to (a figure, or n/a when
     *  {@link #isStatedNa()}), PENDING or not. */
    public boolean isBound() { return stated && (statedDue != null || statedNa); }
    /** The number of the claim this correction corrects; null when it is not a correction. */
    public String getCorrects() { return corrects; }
    /** Whether the claim is a correction: a negative amount, with no floor and no late charge. */
    /** The date the claim is due by, fixed when it was added or set directly by a steward; later changes to
     *  the terms or its date leave it as it is. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    public boolean isCorrection() { return amount.signum() < 0; }
    /** The date the claim was last deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    /** Whether the claim is deferred on {@code today}: OPEN (or PENDING, or SETTLED while bound), deferred until
     *  a date after it, and not bound by a statement. Until then it counts in no total, is not overdue, cannot be
     *  settled and is left unbound by a statement. A claim a statement has bound stays counted, and can be settled,
     *  while bound: its deferral takes effect only once the binding ends. */
    public boolean isDeferredOn(LocalDate today) {
        return (status.isOpen() || status == ClaimStatus.SETTLED) && !isBound()
                && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }
    /** How many proofs the claim has; a claim due above the sheet's proof threshold on its date cannot be
     *  settled or approved while it has none (see {@link CheckProofs}). */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** How many of the claim's proofs are photos; the rest are receipts. */
    public int getProofPhotos() { return proofPhotos; }
    public void setProofPhotos(int proofPhotos) { this.proofPhotos = proofPhotos; }
    /** How many of the claim's proofs are of the kind (receipt or photo). */
    public int proofsOf(String kind) {
        return "photo".equals(kind) ? proofPhotos : "receipt".equals(kind) ? proofs - proofPhotos : 0;
    }
    /** The number of the claim this claim was split off; null when it was not split off another. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }
    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }
    /** The last sheet's today a reminder was written for the claim; null when it was never reminded. */
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** Whether a reminder ever escalated the claim (it is escalated once only). */
    public boolean isEscalated() { return escalated; }
    public void setEscalated(boolean escalated) { this.escalated = escalated; }
    /** The sheet's today the claim went to REVIEW on (its review day); null when it never went to REVIEW. */
    public LocalDate getReviewOn() { return reviewOn; }
    public void setReviewOn(LocalDate reviewOn) { this.reviewOn = reviewOn; }
    /** The sheet's today the claim last went to PENDING on (its pending day); null when it never went to PENDING. */
    public LocalDate getPendingOn() { return pendingOn; }
    public void setPendingOn(LocalDate pendingOn) { this.pendingOn = pendingOn; }
    /** Whether a steward waived its late charge: it bears none from then on, whatever its overdue state. */
    public boolean isWaived() { return waived; }
    public void setWaived(boolean waived) { this.waived = waived; }
    /** Whether the claim is held. A held claim still counts in every total. */
    public boolean isHeld() { return held; }
    public void setHeld(boolean held) { this.held = held; }
    /** The external reference, unique on the sheet without regard to case; null when it has none. */
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }
    /** Its tags (see {@link Tags}): sorted, comma separated; null when it has none. */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }

    /** The people it is shared with and their shares, as stored (see {@link Shares}); null when shared with nobody. */
    public String getShares() { return shares; }
    public void setShares(String shares) { this.shares = shares; }

    /** The user a steward assigned its review to; null when never assigned. */
    public String getReviewUser() { return reviewUser; }
    public void setReviewUser(String reviewUser) { this.reviewUser = reviewUser; }
    /** The reason it was voided with, from the sheet's list then; null when not voided, or voided while the list was empty. */
    public String getVoidReason() { return voidReason; }
    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }
    /** The user who last edited the claim (claim form or amount entry); null when it was never edited. */
    public String getEditedBy() { return editedBy; }
    public void setEditedBy(String editedBy) { this.editedBy = editedBy; }
    /** The bulk settle batch it was settled in; null when settled one at a time, or not settled. */
    public Long getBatch() { return batch; }
    public void setBatch(Long batch) { this.batch = batch; }

    /** When it was added, in the order of change_seq (see {@code RateStore}); a copy keeps its original's. 0 for
     *  claims added before forward-only rates. */
    public long getAddedSeq() { return addedSeq; }
    public void setAddedSeq(long addedSeq) { this.addedSeq = addedSeq; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    public void setPersonId(long personId) { this.personId = personId; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public void setDate(LocalDate date) { this.date = date; }
    public void setNote(String note) { this.note = note; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    public void setNumber(String number) { this.number = number; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    public void setStated(boolean stated) { this.stated = stated; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    public void setStatedNa(boolean statedNa) { this.statedNa = statedNa; }
}
=== ClaimFigure


/** A claim's figure: the due fixed when settled, else the due as shown (late charge and floor included) its
 *  person's last statement bound it to, else its amount at the grade rate in force on
 *  its date, rounded as the sheet's {@link Rounding} has it (null, n/a, when no rate applies). The floor is not
 *  part of a rate figure: {@link Lateness#due} applies it first, before the late charge. */
public final class ClaimFigure {
    private ClaimFigure() {
    }

    /** amount × pct ÷ 100, rounded by {@code mode} to two decimals; null when there is no rate. */
    public static BigDecimal of(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
        return pct == null ? null : amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
    }

    /** The due raised to the floor; null stays null. */
    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
        return due == null || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
    }

    /** The figure the claim has now, given the grade's rate in force on its date. */
    public static BigDecimal of(Claim claim, BigDecimal pct, Rounding rounding) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        return of(claim.getAmount(), pct, rounding.mode(claim));
    }
}
=== Rounding


/** How a sheet rounds a claim's live figures (its rate step and late charge): a claim dated before the
 *  sheet's policy date (the one set, else the sheet's today) rounds half up, one dated on or after it
 *  half to even; but a claim whose date has a rounding mode in force (a dated setting) rounds by that mode.
 *  A correction rounds by the date of the claim it corrects, not its own. */
public final class Rounding {

    private final LocalDate policyDate;

    /** The rounding mode in force on each date, or null when none is (then the policy date decides). */
    private final Function<LocalDate, RoundingMode> modes;

    /** The date of each opened claim on the sheet, by its person and number. */
    private final Map<String, LocalDate> dates = new HashMap<>();

    public Rounding(LocalDate policyDate, List<Claim> claims) {
        this(policyDate, date -> null, claims);
    }

    public Rounding(LocalDate policyDate, Function<LocalDate, RoundingMode> modes, List<Claim> claims) {
        this.policyDate = policyDate;
        this.modes = modes;
        for (Claim claim : claims) {
            if (claim.getNumber() != null) {
                dates.put(key(claim.getPersonId(), claim.getNumber()), claim.getDate());
            }
        }
    }

    /** The sheet's rounding, knowing every claim on it (so a correction finds the claim it corrects). */
    public static Rounding of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims) {
        LocalDate policy = settings.policyDate(sheetId);
        return new Rounding(policy != null ? policy : sheets.today(sheetId), settings.roundings(sheetId),
                claims.list(sheetId));
    }

    /** The date the claim rounds by: its own, or for a correction the date of the claim it corrects. */
    public LocalDate date(Claim claim) {
        LocalDate date = claim.getDate();
        if (claim.getCorrects() != null) {
            date = dates.getOrDefault(key(claim.getPersonId(), claim.getCorrects()), date);
        }
        return date;
    }

    /** The rounding of the claim's live figures. */
    public RoundingMode mode(Claim claim) {
        RoundingMode mode = modes.apply(date(claim));
        if (mode != null) {
            return mode;
        }
        return policyDate != null && date(claim).isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    private static String key(long personId, String number) {
        return personId + "/" + number;
    }
}
=== Lateness


/** What a sheet's late charge follows: each claim's due-by (fixed when it was added), the sheet's late
 *  percent in force on each date and its today; and the sheet's floor in force on each claim's date. An overdue claim (OPEN or PENDING, not deferred, due-by before today) gains, for every full 30 days it is
 *  overdue, the late percent in force on that boundary (its due-by plus 30, 60, 90 ... days) of its figure plus the
 *  charges of the boundaries before it (compounding), each rounded as the sheet's {@link Rounding} has the claim, the charges added up (a boundary at 0.00 adds nothing). A statement binds a claim's due as shown, its
 *  charge and floor included: while bound, its charge no longer follows today. Settling freezes it into the settled due. The floor is applied first: a live due is its figure raised to
 *  the floor in force on the claim's date (none for a correction), plus the late charge worked out on that floored figure. A claim whose person's grade in force on its date has grace
 *  days in force on that date is overdue only when its due-by plus the grace is before today, and its 30-day
 *  boundaries count from its due-by plus the grace ({@link #graceBy}). */
public record Lateness(Function<LocalDate, BigDecimal> latePcts, Function<LocalDate, BigDecimal> floors,
        LocalDate today, Rounding rounding, Function<Claim, LocalDate> graceBy) {

    /** The days in each step of the late charge. */
    private static final int PERIOD_DAYS = 30;

    public static Lateness of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims,
            PersonStore people) {
        return new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), sheets.today(sheetId),
                Rounding.of(sheetId, settings, sheets, claims),
                graced(settings.graces(sheetId), id -> people.find(sheetId, id)));
    }

    /** Each claim's due-by plus the grace days in force on its date for its person's grade then (its due-by
     *  when none), given the grace days by grade and date and each person by id. */
    public static Function<Claim, LocalDate> graced(BiFunction<String, LocalDate, Integer> graces,
            Function<Long, Person> people) {
        return claim -> {
            Person person = people.apply(claim.getPersonId());
            Integer grace = person == null || claim.getDueBy() == null ? null
                    : graces.apply(person.gradeOn(claim.getDate()), claim.getDate());
            return grace == null ? claim.getDueBy() : claim.getDueBy().plusDays(grace);
        };
    }

    /** Whether the claim is overdue: OPEN (or PENDING), not deferred, with its due-by plus any grace before today. */
    public boolean overdue(Claim claim) {
        return claim.getStatus().isOpen() && today != null && !claim.isDeferredOn(today) && claim.getDueBy() != null
                && graceBy.apply(claim).isBefore(today);
    }

    /** The late charge on a claim whose floored rate figure is {@code figure}; none on a correction, nor on a
     *  claim whose charge was waived, nor on one bound by a statement (its bound due has its charge in it). */
    public BigDecimal charge(Claim claim, BigDecimal figure) {
        if (figure == null || !claim.getStatus().isOpen() || today == null || claim.isCorrection() || claim.isBound()
                || claim.isDeferredOn(today) || claim.isWaived()) {
            return BigDecimal.ZERO.setScale(2);
        }
        LocalDate from = graceBy.apply(claim);
        long overdue = ChronoUnit.DAYS.between(from, today);
        long periods = overdue <= 0 ? 0 : overdue / PERIOD_DAYS;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = latePcts.apply(from.plusDays(n * PERIOD_DAYS));
            total = total.add(ClaimFigure.of(figure.add(total), pct, rounding.mode(claim)));
        }
        return total;
    }

    /** The floor in force on the claim's date. */
    public BigDecimal floor(Claim claim) {
        return floors.apply(claim.getDate());
    }

    /** The claim's due now: its settled due, else the due its person's last statement bound it to, else the greater
     *  of its floor and its figure, plus the late charge worked out on that floored figure (a correction has no floor
     *  and no charge). */
    public BigDecimal due(Claim claim, BigDecimal pct) {
        return dueOf(claim, ClaimFigure.of(claim, pct, rounding));
    }

    /** The claim's due now, given its figure (see {@link ClaimFigure}). */
    public BigDecimal dueOf(Claim claim, BigDecimal figure) {
        if (figure == null || claim.getSettledDue() != null || claim.isBound()) {
            return figure;
        }
        BigDecimal floored = claim.isCorrection() ? figure : ClaimFigure.floored(figure, floor(claim));
        return floored.add(charge(claim, floored));
    }
}
=== ClaimResponse


/** A claim as the front end reads it: the amount with two decimals, the date as yyyy-MM-dd,
 *  the status by name, the number as given when opened (FY<yyyy>-<n>, 1, 2, ... given before, or <period>-<n> / X-<n>; null when it has none), the due fixed when
 *  settled with two decimals (null when it has none, so its due is worked out from the current rate), and who opened it
 *  (null until opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound while it had none), whether it was bound to n/a (its rate had ended), and the number of the claim a correction corrects
 *  (null when it is not a correction), and the date its live figures round by (its own, or for a
 *  correction that of the claim it corrects), and the date it is due by, fixed when it was added, and its status log
 *  (see {@link ClaimLogStore}), oldest first, and whether it is deferred on the sheet's today (see
 *  {@link Claim#isDeferredOn}; a VOID claim deferred until after it shows as deferred too) and the date it was deferred until (null when never deferred), and how many proofs it has, and the number of the claim it was
 *  split off (null when it was not split off another), and whether it is a late entry (added while its period was soft-closed),
 *  and the last date it was reminded on (null when never reminded), and its external reference (null when it has none), and its tags, sorted (empty when it has none),
 *  and the reason it was voided with (null when none), and its comments (see {@link ClaimCommentStore}), oldest first,
 *  and the bulk settle batch it was settled in (null when settled one at a time, or not settled), and its lines
 *  (see {@link ClaimLineStore}), in the order added, and when it was added (see {@link Claim#getAddedSeq}), and its
 *  review day, the sheet's today it went to REVIEW on (null when it never went to REVIEW), and whether a steward waived its late charge,
 *  and how many of its proofs are of each kind (receipt, photo), by kind, and whether it is held (see {@link Claim#isHeld}),
 *  and the people it is shared with and their shares (see {@link Shares}), in the order shared (empty when none),
 *  and the user a steward assigned its review to (null when never assigned),
 *  and its pending day, the sheet's today it last went to PENDING on (null when it never went to PENDING). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, boolean statedNa, String corrects, String roundsBy,
        String dueBy, List<String> log, boolean deferred, String deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, String remindedOn, String ref, List<String> tags, String voidReason,
        List<String> comments, Long batch, List<String> lines, long added, String reviewOn, boolean waived,
        java.util.Map<String, Integer> proofKinds, boolean held, List<Holder> shares, String reviewUser,
        String pendingOn) {
    /** One holder of a share of the claim: the person's id and their share, with two decimals. */
    public record Holder(long personId, String share) {
    }

    public static ClaimResponse from(Claim c) {
        return from(c, c.getDate());
    }

    public static ClaimResponse from(Claim c, Rounding rounding) {
        return from(c, rounding.date(c));
    }

    public static ClaimResponse from(Claim c, LocalDate roundsBy) {
        return new ClaimResponse(c.getId(), c.getPersonId(), c.getAmount().toPlainString(), c.getDate().toString(),
                c.getNote(), c.getStatus().name(), c.getNumber(),
                c.getSettledDue() == null ? null : c.getSettledDue().setScale(2).toPlainString(),
                c.getOpenedBy(), c.isStated(),
                c.getStatedDue() == null ? null : c.getStatedDue().setScale(2).toPlainString(), c.isStatedNa(),
                c.getCorrects(), roundsBy.toString(), c.getDueBy().toString(), List.of(),
                false, c.getDeferredUntil() == null ? null : c.getDeferredUntil().toString(), c.getProofs(),
                c.getSplitFrom(), c.isLateEntry(), c.getRemindedOn() == null ? null : c.getRemindedOn().toString(), c.getRef(),
                Tags.list(c.getTags()), c.getVoidReason(), List.of(), c.getBatch(), List.of(), c.getAddedSeq(),
                c.getReviewOn() == null ? null : c.getReviewOn().toString(), c.isWaived(), kinds(c), c.isHeld(),
                Shares.list(c.getShares()).stream().map(h -> new Holder(h.personId(), h.share().toPlainString())).toList(),
                c.getReviewUser(), c.getPendingOn() == null ? null : c.getPendingOn().toString());
    }

    private static java.util.Map<String, Integer> kinds(Claim c) {
        java.util.Map<String, Integer> kinds = new java.util.LinkedHashMap<>();
        for (String kind : net.officefloor.hq.app.setting.SettingStore.KINDS) {
            kinds.put(kind, c.proofsOf(kind));
        }
        return kinds;
    }

    /** The same claim with its status log lines, oldest first. */
    public ClaimResponse withLog(List<String> lines) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, lines, deferred, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason, comments, batch, this.lines, added, reviewOn, waived, proofKinds, held, shares, reviewUser, pendingOn);
    }

    /** The same claim with its comment lines, oldest first. */
    public ClaimResponse withComments(List<String> lines) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, log, deferred, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason, lines, batch, this.lines, added, reviewOn, waived, proofKinds, held, shares, reviewUser, pendingOn);
    }

    /** The same claim with its lines, in the order added. */
    public ClaimResponse withLines(List<String> lines) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, log, deferred, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason, comments, batch, lines, added, reviewOn, waived, proofKinds, held, shares, reviewUser, pendingOn);
    }

    /** The same claim, deferred when OPEN, PENDING or SETTLED and not bound by a statement (see
     *  {@link Claim#isDeferredOn}), or VOID (a voided claim still shows its deferral, though it counts
     *  nowhere), and deferred until a date after the sheet's {@code today}. */
    public ClaimResponse on(LocalDate today) {
        boolean bound = stated && (statedDue != null || statedNa);
        boolean now = ((!bound && (ClaimStatus.OPEN.name().equals(status) || ClaimStatus.PENDING.name().equals(status)
                        || ClaimStatus.SETTLED.name().equals(status))) || ClaimStatus.VOID.name().equals(status))
                && deferredUntil != null && today != null
                && today.toString().compareTo(deferredUntil) < 0;
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, log, now, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason, comments, batch, lines, added, reviewOn, waived, proofKinds, held, shares, reviewUser, pendingOn);
    }
}
=== ClaimStatus

/** Where a claim stands. Only OPEN, PENDING and SETTLED claims count toward the totals; a PENDING claim
 *  (settled by a clerk above the clerk limit, awaiting a steward) is handled as an OPEN one, and a
 *  statement binds it like any other claim that counts. A DELETED claim (a deleted DRAFT) counts nowhere,
 *  and may be restored to a DRAFT only on the sheet's today it was deleted (see {@link CheckClerkLimit}).
 *  A REVIEW claim (opened while its due is above the review threshold in force on its date) awaits a
 *  steward's review, which makes it OPEN; until then it counts in no total and has no number. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim may move from this status to {@code next}: DRAFT to OPEN, OPEN to PENDING or
     *  SETTLED, PENDING to SETTLED (approved) or OPEN (rejected), and DRAFT, OPEN or PENDING to VOID;
     *  SETTLED to VOID too, though only a steward within days of settling it (see {@link CheckClerkLimit}).
     *  DRAFT to DELETED, and DELETED back to DRAFT (restored). DRAFT to REVIEW (opened above the review
     *  threshold), REVIEW to OPEN (reviewed) or VOID. VOID is final. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
