304	/** Moves the claim to the new status, refusing a change its current status does not allow.  Opening
305	 *  records who opened it; settling (or a steward's approval) gives a claim that has none its next number (see {@link Numbering}),
306	 *  and a voided claim keeps the number it has, which is never reused. Settling fixes its due at its person's
307	 *  grade rate in force on the claim's date, rounded as the sheet's policy date has it (none when no rate of the grade applies then),
308	 *  or at the figure its person's last statement bound it to, plus the late charge it has then, and at least the sheet's floor (frozen in).
309	 *  A clerk's settle above the clerk limit makes it PENDING instead (see {@link CheckClerkLimit}); a steward's
310	 *  approval settles a PENDING claim, frozen then at its figure (the one its person's last statement bound
311	 *  it to, if any), and a rejection moves it back to OPEN, still bound by that statement if it included it.
312	 *  The user who opened a claim, or who last edited it, may not settle or approve it, and a claim deferred on the sheet's today may not be settled.
313	 *  Opening a DRAFT is refused while its person already has as many OPEN or PENDING claims in its period as the period's cap.
314	 *  A claim opened to REVIEW records who opened it.
315	 *  While the sheet has void reasons, a void needs one of them (the input's reason), kept on the claim. */
316	public class ApplyStatus {
317	    public void apply(@Val StatusInput input, @Val StatusMove move, @Val Claim claim, ClaimStore store, PersonStore people,
318	            RateStore rates, SettingStore settings, SheetStore sheets, PeriodStore periods,
319	            VoidReasonStore voidReasons, Out<StatusChange> change)
320	            throws InvalidSheetException {
321	        ClaimStatus from = move.from();
322	        ClaimStatus to = move.to();
323	        if (input.status() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
324	                && claim.getOpenedBy().equals(input.user())) {
325	            throw new InvalidSheetException("The user who opened a claim cannot "
326	                    + (input.review() ? "approve" : "settle") + " it");
327	        }
328	        if (input.status() == ClaimStatus.SETTLED && claim.getEditedBy() != null
329	                && claim.getEditedBy().equals(input.user())) {
330	            throw new InvalidSheetException("The user who last edited a claim cannot "
331	                    + (input.review() ? "approve" : "settle") + " it");
332	        }
333	        if (input.status() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
334	            throw new InvalidSheetException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
335	        }
336	        String voidReason = null;
337	        if (to == ClaimStatus.VOID) {
338	            List<String> reasons = voidReasons.list(claim.getSheetId());
339	            if (!reasons.isEmpty()) {
340	                if (input.reason().isEmpty()) {
341	                    throw new InvalidSheetException("A void needs a reason from the sheet's list");
342	                }
343	                if (!reasons.contains(input.reason())) {
344	                    throw new InvalidSheetException(input.reason() + " is not a void reason on the sheet");
345	                }
346	                voidReason = input.reason();
347	            }
348	        }
349	        // A settle as of a date fixes its due as the claim stood at the end of that date.
350	        BigDecimal dueThen = input.status() == ClaimStatus.SETTLED && input.on() != null
351	                ? dueAsOf(claim, input.on(), store, people, rates, settings, sheets) : null;
352	        if (from == ClaimStatus.DRAFT && (to == ClaimStatus.OPEN || to == ClaimStatus.REVIEW)) {
353	            ClaimPeriods.refuseCapped(periods, store, claim);
354	            ClaimPeriods.refuseMaxOpen(settings, store, claim);
355	        }
356	        if (!from.canBecome(to) || !store.move(claim, from, to)) {
357	            throw new InvalidSheetException("A " + from + " claim cannot become " + to);
358	        }
359	        // The due to freeze is worked out while the claim is still OPEN or PENDING, so it takes its late charge in.
360	        BigDecimal settledDue = null;
361	        if (to == ClaimStatus.SETTLED && input.on() != null) {
362	            settledDue = dueThen;
363	        } else if (to == ClaimStatus.SETTLED) {
364	            Person person = people.find(claim.getSheetId(), claim.getPersonId());
365	            BigDecimal pct = person == null ? null : rates.forClaim(claim).find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
366	            settledDue = Lateness.of(claim.getSheetId(), settings, sheets, store, people).due(claim, pct);
367	        }
368	        claim.setStatus(to);
369	        if (to == ClaimStatus.VOID) {
370	            claim.setVoidReason(voidReason);
371	        }
372	        if (to == ClaimStatus.SETTLED && claim.getNumber() == null) {
373	            claim.setNumber(Numbering.next(claim.getSheetId(), claim.getDueBy(), store, settings, sheets, periods));
374	        }
375	        if (from == ClaimStatus.DRAFT && (to == ClaimStatus.OPEN || to == ClaimStatus.REVIEW)) {
376	            claim.setOpenedBy(input.user());
377	        }
378	        if (to == ClaimStatus.REVIEW) {
379	            store.markReview(claim, sheets.today(claim.getSheetId()));
380	        }
381	        if (to == ClaimStatus.PENDING) {
382	            store.markPending(claim, sheets.today(claim.getSheetId()));
383	        }
384	        if (to == ClaimStatus.SETTLED) {
385	            claim.setSettledDue(settledDue);
386	        }
387	        change.set(new StatusChange(claim.getNumber()));
388	    }
389	    /** The claim's due as it stood at the end of the date, as the as-of view works it out (see
390	     *  {@link net.officefloor.hq.app.history.History}): the claim, its person, rates and settings as they stood
391	     *  then, the date standing in for the sheet's today. Refused when the date is after the sheet's today, or the
392	     *  claim or its person was not on the sheet then. */
393	    static BigDecimal dueAsOf(Claim claim, LocalDate on, ClaimStore store, PersonStore people, RateStore rates,
394	            SettingStore settings, SheetStore sheets) throws InvalidSheetException {
395	        String sheetId = claim.getSheetId();
396	        if (on.isAfter(sheets.today(sheetId))) {
397	            throw new InvalidSheetException("The settle date is after the sheet's today");
398	        }
399	        List<Claim> all = store.listAsOf(sheetId, on);
400	        Claim then = all.stream().filter(c -> c.getId() == claim.getId()).findFirst().orElse(null);
401	        if (then == null || then.getStatus() == ClaimStatus.DELETED) {
402	            throw new InvalidSheetException("The claim was not on the sheet on " + on);
403	        }
404	        Person person = people.findAsOf(sheetId, then.getPersonId(), on);
405	        if (person == null) {
406	            throw new InvalidSheetException("The claim's person was not on the sheet on " + on);
407	        }
408	        RateStore ratesThen = rates.asOf(on);
409	        SettingStore settingsThen = settings.asOf(on);
410	        LocalDate policy = settingsThen.policyDate(sheetId);
411	        Rounding rounding = new Rounding(policy != null ? policy : on, settingsThen.roundings(sheetId), all);
412	        Lateness lateness = new Lateness(settingsThen.latePcts(sheetId), settingsThen.floors(sheetId), on, rounding,
413	                Lateness.graced(settingsThen.graces(sheetId), id -> id == person.getId() ? person : null));
414	        BigDecimal pct = ratesThen.forClaim(then).find(sheetId, person.gradeOn(then.getDate()), then.getDate());
415	        return lateness.due(then, pct);
416	    }
417	}
